INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3001, "ヤマト", 2.1, 2, 3001100, 1, 0.0, 130011, -416.5, "2024/10/31 12:00:00", "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 100, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3001, "ヤマト", 5.68, 2, 3001101, 4, 0.0, 130011, -416.5, "2024/10/31 12:00:00", "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 101, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3001, "ヤマト", 0.0, 1, 3001102, 1, 0.0, 130011, -416.5, "2024/10/31 12:00:00", "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 102, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3002, "フブキ", 0.0, 1, 3002100, 1, 0.0, 130211, -416.5, "2024/10/31 12:00:00", "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 100, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3002, "フブキ", 0.0, 1, 3002101, 1, 0.0, 130211, -416.5, "2024/10/31 12:00:00", "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 101, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3002, "フブキ", 8.53, 2, 3002102, 5, 0.0, 130211, -416.5, "2024/10/31 12:00:00", "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 102, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3002, "フブキ", 5.67, 1, 3002103, 7, 0.0, 130211, -416.5, "2024/10/31 12:00:00", "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 103, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3002, "フブキ", 0.0, 1, 3002104, 1, 0.0, 130211, -416.5, "2024/10/31 12:00:00", "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 104, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3004, "フブキ", 0.0, 3, 3002300, 3, 0.0, 130211, -416.5, "2024/10/31 12:00:00", "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 300, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3005, "フブキ", 0.0, 7, 3002400, 7, 0.0, 130211, -416.5, "2024/10/31 12:00:00", "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 301, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3003, "フブキ", 4.4, 1, 3003200, 2, 0.0, 130211, -416.5, "2024/10/31 12:00:00", "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 200, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3003, "フブキ", 0.0, 7, 3003201, 7, 0.0, 130211, -416.5, "2024/10/31 12:00:00", "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 201, "2030/01/01 14:59:59");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3003, "フブキ", 5.6, 2, 3003202, 1, 0.0, 130211, -416.5, "2024/10/31 12:00:00", "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 202, "2030/01/01 14:59:59");
